WITH with_windows AS (SELECT *, COUNT(quantity) OVER (PARTITION BY order_id) AS order_id_count_quantity, LAST_VALUE(unit_price) IGNORE NULLS OVER (PARTITION BY product_id, order_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_unit_price, ROUND(quantity / SUM(quantity) OVER (PARTITION BY order_id, product_id), 4) AS quantity_share FROM order_items) SELECT CASE WHEN order_id_count_quantity >= 13 THEN 'LARGE' ELSE 'SMALL' END AS order_id_count_quantity_tier, CASE WHEN unit_price >= 420 THEN 'PREMIUM' ELSE 'STANDARD' END AS unit_price_tier, order_id, BIT_AND(quantity) AS quantity_bit_and, COUNT(*) AS num_rows, ROUND(AVG(quantity), 2) AS avg_quantity, CORR(quantity, unit_price) AS corr_quantity_unit_price, BIT_OR(quantity) AS quantity_bit_or FROM with_windows GROUP BY order_id_count_quantity_tier, unit_price_tier, order_id ORDER BY order_id_count_quantity_tier DESC;
